import math


def cosine_similarity(a, b):
    dot = sum(x * y for x, y in zip(a, b))
    norm_a = math.sqrt(sum(x * x for x in a))
    norm_b = math.sqrt(sum(y * y for y in b))
    return dot / (norm_a * norm_b)


# Toy embedding vectors standing in for a real model's output
embeddings = {
    "no puedo iniciar sesion": [0.9, 0.1, 0.4],
    "olvide mi contrasena": [0.8, 0.2, 0.5],
    "el envio llega tarde": [0.1, 0.9, 0.2],
}

pairs = [
    ("no puedo iniciar sesion", "olvide mi contrasena"),
    ("no puedo iniciar sesion", "el envio llega tarde"),
]

for text_a, text_b in pairs:
    score = cosine_similarity(embeddings[text_a], embeddings[text_b])
    print(f"{text_a!r} vs {text_b!r}: {score:.3f}")
